function Nx.ModQuests:Load1()
    local ModQuests = Nx.ModQuests:Data1()
    local count = 0
    for key, val in pairs(ModQuests) do
        Nx.Quests[key] = val
        count = count + 1
    end
    ModQuests = {}
    return count
end

function Nx.ModQuests:Clear1()
    --ModQuests = {}
end
